def solve():
    from collections import Counter

    def is_alternating(s):
        prev_char = s[0]
        for i in range(1, len(s)):
            if s[i] == prev_char:
                return False
            prev_char = s[i]
        return True

    def can_be_alternating(s):
        char_count = Counter(s)
        if len(char_count) > 2:
            return False
        if len(char_count) == 1:
            return True
        if len(char_count) == 2:
            if abs(char_count.most_common(1)[0][1] - char_count.most_common(2)[1][1]) > 1:
                return False
            return is_alternating(s)
        return True

    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()
        if can_be_alternating(s):
            print("YES")
        else:
            print("NO")

