def solve():
    from sys import stdin

    def is_reordering_possible(t):
        if t == 1:
            return 'YES'

        odd_count = sum(1 for _ in input().split() if int(_) % 2 != 0)
        even_count = t - odd_count

        if even_count < odd_count:
            return 'NO'
        else:
            return 'YES'

    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        print(is_reordering_possible(n))

