def solve():
    import sys
    input = lambda: input().strip()

    def is_beautiful_sequence(seq):
        # Check if there's any index i such that seq[i] == i+1
        return any(x == i + 1 for i, x in enumerate(seq))

    t = int(input())
    for _ in range(t):
        n = int(input())
        seq = list(map(int, input().split()))
        if is_beautiful_sequence(seq):
            print("YES")
        else:
            print("NO")

