def solve():
    import sys

    input = sys.stdin.read
    lines = input().splitlines()
    t = int(lines[0])
    n_values = lines[1:]

    for n in n_values:
        n = int(n)
        if n == 6:
            print(0)
        else:
            min_diff = (n - 2) // 3
            print(min_diff)

