from collections import deque

def solve():
    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        dialog = input().strip()
        queue = deque()

        for i in range(n):
            if dialog[i] == "Q":
                queue.append("Q")
            elif dialog[i] == "A":
                if not queue:
                    print("No")
                    break
                else:
                    queue.popleft()
        else:
            if not queue:
                print("Yes")
            else:
                print("No")

